#!/usr/bin/env python3
"""Render the static File Manager website. Signed configuration files are never edited."""
from pathlib import Path
import html

SITE=Path(__file__).parent/'site'
ORIGIN='https://metosapps.github.io/FileManagerGalaxyConfig/'
STORE='https://galaxystore.samsung.com/detail/com.filegx.appsmanager'
EMAIL='chennoufo11@gmail.com'
SYMBOLS='''<svg xmlns="http://www.w3.org/2000/svg" style="display:none" aria-hidden="true"><defs>
<symbol id="folder" viewBox="0 0 24 24"><path d="M3 7V5a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7Z"/></symbol>
<symbol id="search" viewBox="0 0 24 24"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></symbol>
<symbol id="chart" viewBox="0 0 24 24"><path d="M4 3v17h17M9 15V9m5 6V5m5 10v-3"/></symbol>
<symbol id="lock" viewBox="0 0 24 24"><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/></symbol>
<symbol id="wifi" viewBox="0 0 24 24"><path d="M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0m-10 4a5 5 0 0 1 6 0"/><circle cx="12" cy="20" r=".6"/></symbol>
<symbol id="zip" viewBox="0 0 24 24"><path d="M7 3h7l4 4v14H5V3h2Zm7 0v5h4m-8-5v2m0 2v2m0 2v2"/><rect x="9" y="15" width="3" height="4" rx="1"/></symbol>
<symbol id="trash" viewBox="0 0 24 24"><path d="M3 6h18M8 6V3h8v3M6 6l1 15h10l1-15M10 10v7m4-7v7"/></symbol>
<symbol id="palette" viewBox="0 0 24 24"><path d="M21 12a9 9 0 1 0-9 9h2a2 2 0 0 0 1-3c-1-2 0-3 2-3h1a3 3 0 0 0 3-3Z"/><circle cx="7" cy="10" r=".8"/><circle cx="11" cy="6" r=".8"/><circle cx="16" cy="8" r=".8"/></symbol>
<symbol id="arrow" viewBox="0 0 24 24"><path d="M5 12h14m-6-6 6 6-6 6"/></symbol>
<symbol id="bag" viewBox="0 0 24 24"><path d="M4 8h16l-1 13H5L4 8Zm4 0V6a4 4 0 0 1 8 0v2"/></symbol>
<symbol id="menu" viewBox="0 0 24 24"><path d="M4 6h16M4 12h16M4 18h16"/></symbol>
<symbol id="check" viewBox="0 0 24 24"><path d="m5 12 4 4L19 6"/></symbol>
<symbol id="close" viewBox="0 0 24 24"><path d="m6 6 12 12M6 18 18 6"/></symbol>
<symbol id="left" viewBox="0 0 24 24"><path d="m14 6-6 6 6 6"/></symbol>
<symbol id="right" viewBox="0 0 24 24"><path d="m10 6 6 6-6 6"/></symbol>
<symbol id="mail" viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/></symbol>
</defs></svg>'''
def icon(name):return '<svg aria-hidden="true"><use href="#'+name+'"></use></svg>'
def badge():return '<a class="store-badge" href="'+STORE+'" target="_blank" rel="noopener noreferrer" aria-label="View File Manager in Galaxy Store" aria-describedby="store-availability"><span class="bag">'+icon('bag')+'</span><span><small>View in</small><strong>Galaxy Store</strong></span></a>'
def header():return '''<a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="wrap header-row"><a class="brand" href="index.html"><img src="icon.png" width="44" height="44" alt=""><span>File Manager</span></a><button class="menu-toggle" data-menu aria-label="Open navigation" aria-expanded="false" aria-controls="navigation">'''+icon('menu')+'''</button><nav class="nav" id="navigation" aria-label="Main navigation"><a href="index.html#features">Features</a><a href="index.html#how-it-works">How it works</a><a href="index.html#screenshots">Screenshots</a><a href="support.html">Support</a><a class="nav-cta" href="'''+STORE+'''" target="_blank" rel="noopener noreferrer">Galaxy Store ↗</a></nav></div></header>'''
def footer():return '''<footer class="site-footer"><div class="wrap"><div class="footer-row"><a class="brand" href="index.html"><img src="icon.png" width="35" height="35" alt="">File Manager</a><nav class="footer-links" aria-label="Footer"><a href="privacy.html">Privacy Policy</a><a href="terms.html">Terms of Use</a><a href="support.html">Support</a><a href="mailto:'''+EMAIL+'''">Contact</a></nav></div><p class="fine-print">© 2026 File Manager. Android package: com.filegx.appsmanager.<br>Galaxy Store is a trademark of Samsung Electronics. File Manager is an independent app; this website does not imply Samsung endorsement.</p></div></footer>'''
def page(filename,title,description,body):
    meta='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0b3bbb"><meta name="color-scheme" content="light"><meta http-equiv="Content-Security-Policy" content="default-src 'self'; img-src 'self' data:; style-src 'self'; script-src 'self'; object-src 'none'; base-uri 'self'; frame-src 'none'; form-action 'none'; connect-src 'none'"><title>'''+html.escape(title)+'''</title><meta name="description" content="'''+html.escape(description,quote=True)+'''"><link rel="canonical" href="'''+ORIGIN+('' if filename=='index.html' else filename)+'''"><link rel="icon" href="icon.png" type="image/png"><link rel="apple-touch-icon" href="icon.png"><meta property="og:type" content="website"><meta property="og:title" content="'''+html.escape(title,quote=True)+'''"><meta property="og:description" content="'''+html.escape(description,quote=True)+'''"><meta property="og:url" content="'''+ORIGIN+('' if filename=='index.html' else filename)+'''"><meta property="og:image" content="'''+ORIGIN+'''assets/social-preview.png"><meta name="twitter:card" content="summary_large_image"><link rel="stylesheet" href="styles.css"><script src="app.js" defer></script></head><body>'''
    # The sprite is code-native; display via the HTML hidden attribute rather than inline style under CSP.
    sprite=SYMBOLS.replace('style="display:none"','hidden')
    (SITE/filename).write_text(meta+sprite+header()+body+footer()+'</body></html>')

features=[('folder','Everyday file tools','Browse folders and copy, move, rename or share files. Choose a list or grid to see them your way.'),('search','Find the right file','Search by name and filter by file type. Keep useful locations in Favorites and return to recent files.'),('chart','A clearer view of storage','See a breakdown by file type and find duplicate files with exactly the same content.'),('zip','Create & open ZIPs','Keep project files together. Create and extract ZIP archives on supported local storage.'),('lock','A private encrypted Vault','Protect selected files with a passphrase. Lock the Vault when you finish; keep your passphrase safe.'),('wifi','Phone to browser, locally','Share a folder over local Wi-Fi using a PIN. Use a trusted network: this connection is not encrypted.'),('trash','A second chance with Trash','Restore supported locally deleted items before permanent removal. Selected Android folders have different capabilities.'),('palette','Make room for your style','Choose light or dark mode, colour themes and file icon styles. A built-in language picker helps you feel at home.')]
feature_html=''.join('<article class="feature-card"><div class="feature-icon">'+icon(i)+'</div><h3>'+h+'</h3><p>'+p+'</p></article>' for i,h,p in features)
shots=[('01-home','Your files, organised'),('02-browse','Copy, move & organise'),('03-search','Search without scrolling'),('04-analyzer','Understand your storage'),('05-vault','Protect selected files'),('06-transfer','Share over local Wi-Fi'),('07-appearance','Choose your look'),('08-archives','Open & create ZIPs')]
gallery=''.join('<button class="shot" data-shot="assets/'+n+'.webp" data-title="'+html.escape(t,quote=True)+'" aria-label="Enlarge screenshot: '+html.escape(t,quote=True)+'"><img src="assets/'+n+'.webp" alt="File Manager — '+html.escape(t,quote=True)+'" width="887" height="1774" loading="lazy" decoding="async"><span>'+t+'</span></button>' for n,t in shots)
body='''<main id="main"><section class="hero"><div class="wrap hero-grid"><div class="hero-copy"><span class="edition-label"><i></i> File Manager · Galaxy Store edition</span><h1>Your files.<br><span class="accent">In good order.</span></h1><p>Find that document. Tidy your folders. Keep private files protected. Everyday tools for the files on your Android device.</p><div class="hero-actions">'''+badge()+'''<a class="text-link" href="#features">Explore the app '''+icon('arrow')+'''</a></div><p class="release-note" id="store-availability">Galaxy Store release in progress. The store listing opens when published; availability may vary by region.</p><div class="hero-points"><span>'''+icon('check')+'''Local file tools</span><span>'''+icon('check')+'''No app account</span><span>'''+icon('check')+'''Android 7.0+</span></div></div><div class="hero-visual"><div class="phone"><img src="assets/app-home.png" width="1080" height="2400" alt="File Manager Home screen with storage usage and file categories" fetchpriority="high"></div><img class="float-icon" src="icon.png" width="117" height="117" alt=""><div class="float-card top"><span class="card-symbol">'''+icon('search')+'''</span>Less searching.<br>More finding.</div><div class="float-card bottom"><span class="card-symbol">'''+icon('lock')+'''</span>Private files.<br>Your passphrase.</div></div></div></section><div class="platform-strip"><div class="wrap platform-row"><span><b>Browse</b> folders & documents</span><span><b>Understand</b> your storage</span><span><b>Protect</b> selected files</span><span><b>Share</b> over local Wi-Fi</span></div></div><section class="section" id="features"><div class="wrap"><div class="section-head"><div><p class="eyebrow">A practical toolkit</p><h2>One app.<br>A little more order.</h2></div><p>The tools you need to manage your files, with a clear view of what is happening.</p></div><div class="feature-grid">'''+feature_html+'''</div></div></section><section class="section how-section" id="how-it-works"><div class="wrap how-grid"><div class="how-intro"><p class="eyebrow">Start with your files</p><h2>Open. Choose.<br>Make it yours.</h2><p>No File Manager account to create. Give the app access to the files you want to manage, then get on with your day.</p></div><div class="steps"><article class="step"><span class="step-number">01</span><div><h3>Choose what the app can access</h3><p>Select a supported folder with Android’s picker, or review the broader file access permission when you need to manage your local storage.</p></div></article><article class="step"><span class="step-number">02</span><div><h3>Find and organise</h3><p>Open a category, browse a folder or search by name. Select files to copy, move, rename, share or place in a ZIP archive.</p></div></article><article class="step"><span class="step-number">03</span><div><h3>Protect or share, when you choose</h3><p>Move chosen files into the encrypted Vault. Or turn on local Wi-Fi sharing, open the shown address in a browser and enter the PIN. Stop sharing when you finish.</p></div></article></div></div></section><section class="section showcase" id="screenshots"><div class="wrap"><div class="section-head"><div><p class="eyebrow">Take a closer look</p><h2>See what you can do.</h2></div><p>Explore eight feature walkthroughs. Tap any image to open it at full size.</p></div><img class="featured-image" src="assets/featured.webp" width="1774" height="887" alt="File Manager featured graphic: browse local files, search by name, protect files in Vault and share over local Wi-Fi" loading="lazy" decoding="async"><div class="gallery">'''+gallery+'''</div><p class="gallery-note">Illustrated feature previews based on the app. Sample files are used for demonstration.</p></div></section><section class="section" id="questions"><div class="wrap faq-grid"><div><p class="eyebrow">Good to know</p><h2>A few things<br>before you begin.</h2></div><div class="faq-items"><details><summary>Where do my files stay?</summary><p>File tools work with your device’s local storage and the folders you grant access to. File names, paths, search terms and Vault contents are not advertising parameters. Sharing or Wi-Fi transfer happens when you choose it. See the <a href="privacy.html">Privacy Policy</a> for details about app services and hosting.</p></details><details><summary>Can I recover a forgotten Vault passphrase?</summary><p>No. There is no passphrase recovery service. Keep the passphrase safe and back up important files before moving them into the Vault. Removing the app can remove its private Vault and Trash data.</p></details><details><summary>Is Wi-Fi transfer encrypted?</summary><p>No. The connection uses local HTTP and a PIN. Use a trusted Wi-Fi network, share only the intended folder, and stop the server after use. Interrupted transfers do not resume automatically.</p></details><details><summary>Do ZIP and Trash work in every folder?</summary><p>ZIP and recoverable Trash currently work with supported local storage. Folders selected through Android may have different capabilities; deletion there may be permanent. Always read the action and confirmation before deleting files.</p></details><details><summary>Are ads or purchases enabled?</summary><p>Advertising and purchasing are disabled in the current release configuration, and unregistered Pro offers are hidden. Basic local file management does not require a subscription. Any later optional offer must be presented clearly before purchase.</p></details><details><summary>Which languages can I use?</summary><p>A built-in language picker is available. The store description’s language may differ from the interface. Some screens and policies may appear in English, and feature availability can depend on your device and permissions.</p></details></div></div></section><div class="wrap"><section class="support-banner"><div><p class="eyebrow">Here to help</p><h2>Need a hand with your files?</h2><p>Find answers, read the policies or contact File Manager support.</p></div><a class="button" href="support.html">Visit support '''+icon('arrow')+'''</a></section></div></main><dialog class="lightbox" id="gallery-dialog" aria-label="File Manager screenshot gallery"><img class="lightbox-image" alt=""><div class="lightbox-bar"><p data-caption></p><div class="dialog-controls"><button class="icon-button" data-prev aria-label="Previous screenshot">'''+icon('left')+'''</button><button class="icon-button" data-next aria-label="Next screenshot">'''+icon('right')+'''</button><button class="icon-button" data-close aria-label="Close screenshot gallery">'''+icon('close')+'''</button></div></div></dialog>'''
page('index.html','File Manager — Find. Organise. Protect.','Browse, search and organise Android files. Explore ZIP tools, an encrypted Vault, storage analysis and local Wi-Fi sharing in File Manager.',body)

privacy='''<main class="legal-main" id="main"><p class="eyebrow">File Manager · Your information</p><h1>Privacy Policy</h1><p class="legal-meta">Updated 25 October 2026 · Android package com.filegx.appsmanager</p><p class="lead">File Manager helps you manage files locally. It has no app account system and does not send your file contents to an analytics or advertising service.</p><h2>Files and permissions</h2><p>The app accesses local storage or Android-selected folders only with the permissions you grant. It reads and changes files to carry out actions you choose, such as browsing, copying, moving, renaming, ZIP creation, deletion and sharing. File names, paths, search terms and Vault contents are not ad-request parameters.</p><h2>Vault, Trash and preferences</h2><p>Chosen Vault files are encrypted on the device using your passphrase. The passphrase cannot be recovered. Local preferences remain until cleared or the app is removed. Vault and Trash are not cloud-backed up by this app. Uninstalling or clearing app data can remove private Vault and Trash data; export important files first.</p><h2>Sharing and Wi-Fi transfer</h2><p>You decide which files to share or transfer. Wi-Fi transfer exposes the selected folder through a local browser connection with a PIN. The HTTP connection is not encrypted. Use a trusted network and stop sharing after use. Files transferred by your request leave the device for the recipient you choose.</p><h2>Advertising, consent and purchases</h2><p>Test and production advertising and purchasing are currently disabled, and unregistered Pro offers are hidden. The Galaxy build contains Google Mobile Ads, Google User Messaging Platform (UMP) and Samsung IAP integrations for optional services. Their presence does not mean an ad request or purchase is enabled.</p><p>If advertising is enabled in a future configuration and your privacy choices permit it, Google Mobile Ads and UMP may process device, advertising and consent information. Consent is checked before ad requests, and privacy choices are offered in the app when required. Pro ownership removes ads. First-session, file-operation, Vault, permission and purchase flows contain no ad placements.</p><p>Samsung IAP processes store-account and purchase information when optional store purchases are available and used. Store terms and any displayed price apply before payment. The app does not receive your card number from the store.</p><h2>Analytics and crash reporting</h2><p>This build does not transmit Firebase analytics or crash reports. Analytics and crash-reporting preferences default off; no Firebase reporting backend is configured.</p><h2>Configuration and this website</h2><p>The app fetches signed configuration from an app-specific HTTPS endpoint hosted on GitHub Pages. These requests do not contain file names, paths or search terms. Hosting providers may process ordinary connection metadata, such as IP address, user agent and access time, to serve the website and configuration. This website uses no added analytics, advertising scripts, account system or contact form. Email support is handled through your chosen email service.</p><h2>Your choices</h2><p>Manage permissions and remove local app data in Android Settings. You can stop Wi-Fi sharing in the app and choose whether to use the Vault. Back up or export important data before clearing the app. Where required, advertising privacy controls are available in Privacy settings when advertising services are active.</p><h2>Provider information</h2><ul><li><a href="https://policies.google.com/privacy" rel="noopener noreferrer" target="_blank">Google Privacy Policy</a></li><li><a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement" rel="noopener noreferrer" target="_blank">GitHub General Privacy Statement</a></li></ul><h2>Contact</h2><p>For File Manager privacy or support questions, email <a href="mailto:'''+EMAIL+'''">'''+EMAIL+'''</a>. Do not send a Vault passphrase or private documents with an initial support request.</p><p><a href="terms.html">Terms of Use</a> · <a href="support.html">Support</a></p></main>'''
page('privacy.html','Privacy Policy — File Manager','Read how File Manager handles local files, permissions, Vault, Wi-Fi sharing, optional services and support.',privacy)
terms='''<main class="legal-main" id="main"><p class="eyebrow">File Manager · Using the app</p><h1>Terms of Use</h1><p class="legal-meta">Updated 25 October 2026 · Android package com.filegx.appsmanager</p><p class="lead">Use File Manager to manage files you own or are authorised to access. Choose permissions and file actions deliberately, and keep a separate backup of important data.</p><h2>File actions and your choices</h2><p>Copying, moving, renaming, sharing and deleting files can change or remove data. Check the selected files, destination and confirmation before proceeding. Permanent deletion cannot be undone by the app. Android-selected folders may support different operations from local storage. ZIP tools and recoverable Trash are limited to supported local storage.</p><h2>Encrypted Vault</h2><p>The Vault protects selected files with encryption based on your passphrase. There is no recovery service for a forgotten passphrase. Removing the app or clearing its data can remove private Vault and Trash contents. Export or back up important files before doing so.</p><h2>Local Wi-Fi sharing</h2><p>Optional Wi-Fi transfer shares the selected folder over your local network using a PIN. The connection is not encrypted. Only use a trusted network and stop the server when finished. Interrupted transfers do not resume automatically.</p><h2>Optional services</h2><p>Advertising and purchasing are disabled in the current release configuration. Basic local file management does not require a subscription. If optional Pro purchases become available, they are processed by Galaxy Store with the price and terms shown before payment. Restore purchases is available for supported purchases. Advertising, when enabled, must be labelled and subject to privacy choices. Development tests may use official Google demo inventory when explicitly enabled; current test inventory is off.</p><h2>Availability and changes</h2><p>Compatibility depends on your Android version, permissions, storage provider and device. The Galaxy Store release is in progress; a link to the store does not guarantee that the app is available in your region. Updates may change features or fix errors. A store-distributed update must come through the relevant store.</p><h2>Responsible use</h2><p>Do not use the app to access, copy, distribute or delete content without permission. You are responsible for the content you choose to manage or share. File Manager is a general-purpose file tool; it does not provide cloud backup or guaranteed recovery of lost data.</p><h2>Privacy and support</h2><p>The <a href="privacy.html">Privacy Policy</a> explains local data and optional third-party services. For help, contact <a href="mailto:'''+EMAIL+'''">'''+EMAIL+'''</a>. Keep app and device details in the request, and omit private files and passphrases.</p></main>'''
page('terms.html','Terms of Use — File Manager','Read the terms for local file actions, encrypted Vault, Wi-Fi sharing and optional File Manager services.',terms)
support='''<main class="legal-main" id="main"><p class="eyebrow">File Manager · Support</p><h1>A little help,<br>when you need it.</h1><p class="lead">Questions about browsing, file access, the Vault or local Wi-Fi sharing? Contact File Manager support.</p><section class="legal-card" aria-labelledby="contact-heading"><h2 id="contact-heading">Contact support</h2><p><a class="contact-address" href="mailto:'''+EMAIL+'''?subject=File%20Manager%20Support">'''+EMAIL+'''</a></p><div class="button-row"><a class="button" href="mailto:'''+EMAIL+'''?subject=File%20Manager%20Support">'''+icon('mail')+'''Write an email</a><button class="button secondary" data-copy-email>Copy email address</button></div><p class="empty-feedback" data-copy-status role="status" aria-live="polite"></p><p>Please include your app version, Android version, device model and the steps that led to the issue. For a file problem, say whether you used local storage or an Android-selected folder. <strong>Do not send private documents, payment details or a Vault passphrase.</strong></p></section><h2>Quick answers</h2><div class="faq-items"><details open><summary>I cannot see a folder. What should I check?</summary><p>Review file access in Android Settings, or add a supported folder through Android’s folder picker. A previously granted folder can become unavailable after its permission is revoked or the storage is disconnected.</p></details><details><summary>My deleted file is not in Trash.</summary><p>Recoverable Trash works with supported local storage. Deletion from some Android-selected folders is permanent. The app cannot restore a permanently deleted file; check any independent backup you keep.</p></details><details><summary>I forgot my Vault passphrase.</summary><p>There is no recovery option or support override. Keep the passphrase safe. Do not uninstall or clear app data expecting a reset to restore encrypted files.</p></details><details><summary>My computer cannot connect to Wi-Fi sharing.</summary><p>Use the same trusted local network, turn on sharing in the app, and enter the exact address and PIN shown. The connection is unencrypted and may be blocked by network isolation. Stop sharing after use.</p></details><details><summary>Can support recover my files?</summary><p>The app has no cloud copy of your Vault or Trash. Support can help explain the tools and diagnose an issue but cannot recover a forgotten passphrase or guarantee recovery of deleted files.</p></details><details><summary>Where can I find the policies?</summary><p>Read the <a href="privacy.html">Privacy Policy</a> and <a href="terms.html">Terms of Use</a>. Both are available here and readable offline in the app.</p></details></div><div class="legal-card"><h2>Looking for File Manager?</h2><p>The Galaxy Store release is in progress. Use this app-specific link to check the listing when it becomes available.</p><a class="button" href="'''+STORE+'''" target="_blank" rel="noopener noreferrer">Open Galaxy Store '''+icon('arrow')+'''</a></div></main>'''
page('support.html','Support — File Manager','Get help with File Manager permissions, local files, Vault, Trash and Wi-Fi transfer. Contact chennoufo11@gmail.com.',support)
print('Rendered landing page, privacy, terms and support.')
